}

#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int a = 12, b = 0;
    if (b != 0 && a % b == 0)
        cout << "CHIA HET";
    else
        cout << "KHONG HOP LE";
}

#include <algorithm>
#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    vector<long long> a = {3, 4, 7};
    sort(a.begin(), a.end());
    cout << (a[0] > 0 && a[0] > a[2] - a[1] ? "YES" : "NO");
}

