advanced.solutionCode:
#include <algorithm>
#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    vector<long long> a(3);
    for (auto &x : a)
        cin >> x;
    sort(a.begin(), a.end());
    cout << (a[0] > a[2] - a[1] ? "YES" : "NO");
}
